// The CLI's generated files and `pnpm api-schema:generate`: the script renders them with api-schema's
// own files, so `pnpm api-schema:check` covers them, and the committed ones are what it renders.
// Scratch files go under the OS temp directory.

import assert from "node:assert/strict";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test from "node:test";
import { pathToFileURL } from "node:url";
import { renderApiSchema } from "../../api-schema/scripts/generate.ts";
import { renderAgentTypes, type Schema } from "./emit.ts";

const ROOT = join(import.meta.dirname, "..", "..", "..");
const CLI_FILES = ["packages/api-cli/generated/commands.ts", "packages/api-cli/generated/agent-types.ts"];

test("pnpm api-schema:generate renders the CLI's files, and the committed ones are what it renders", () => {
  // generateApiSchema writes, or with --check compares, exactly these files: that is what makes
  // `pnpm api-schema:check` cover the CLI's.
  const schema = JSON.parse(readFileSync(join(ROOT, "packages/api-schema/generated/workshop-api.schema.json"), "utf8")) as Schema;
  const files = renderApiSchema(schema);
  const paths = files.map((file) => file.path);
  for (const path of ["packages/api-schema/generated/workshop-api.schema.json", ...CLI_FILES]) {
    assert.ok(paths.includes(path), path);
  }
  for (const path of CLI_FILES) {
    assert.equal(files.find((file) => file.path === path)!.contents, readFileSync(join(ROOT, path), "utf8"), path);
  }
});

test("agent-types.ts holds the agent declarations, whole and per service, each text line for line", async (t) => {
  const agent = { declarations: "/** `a` and ${b} */\nexport interface A {\n  \"x\"(): void;\n}\n", fragments: { A: "a\n", "not-a-name": "" } };
  const dir = mkdtempSync(join(tmpdir(), "api-cli-generate-"));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  const path = join(dir, "agent-types.ts");
  writeFileSync(path, renderAgentTypes(agent));
  const text = readFileSync(path, "utf8");
  assert.match(text, /^\/\/ Generated by `pnpm api-schema:generate` \(packages\/api-cli\/generator\/emit\.ts\): .*; do not edit\.\n/);
  assert.match(text, /^ {2}"export interface A \{",$/m);
  const module = await import(pathToFileURL(path).href) as { declarations: string; fragments: Record<string, string> };
  assert.deepEqual({ declarations: module.declarations, fragments: module.fragments }, agent);
});
